{
  // Schema reference for wrangler configuration
  "$schema": "node_modules/wrangler/config-schema.json",

  // Name of your worker
  "name": "__change_me__",

  // Entry point for your worker
  "main": "src/worker.tsx",

  // Compatibility settings
  "compatibility_date": "2025-08-21",
  "compatibility_flags": ["nodejs_compat"],

  // Assets configuration
  "assets": {
    "binding": "ASSETS"
  },

  // Durable Objects used for realtime synced state
  "durable_objects": {
    "bindings": [
      {
        "name": "SYNCED_STATE_SERVER",
        "class_name": "SyncedStateServer"
      }
    ]
  },

  // Migrations for Durable Objects (SQLite-backed)
  "migrations": [
    {
      "tag": "v1",
      "new_sqlite_classes": ["SyncedStateServer"]
    }
  ],

  // Observability settings
  "observability": {
    "enabled": true
  },

  // Environment variables
  "vars": {
    // Add your environment variables here
  }
}

import { env } from "cloudflare:workers";
import { render, route } from "rwsdk/router";
import { defineApp } from "rwsdk/worker";
import {
  SyncedStateServer,
  syncedStateRoutes,
} from "rwsdk/use-synced-state/worker";

import { Document } from "@/app/document";
import { setCommonHeaders } from "@/app/headers";
import { Home } from "@/app/pages/home";

// Export the Durable Object so Cloudflare can find it
export { SyncedStateServer };

export type AppContext = {};

export default defineApp([
  setCommonHeaders(),
  ({ ctx }) => {
    // setup ctx here
    ctx;
  },
  // Register the realtime synced state routes (forwards to the
  // SYNCED_STATE_SERVER Durable Object namespace)
  ...syncedStateRoutes(() => env.SYNCED_STATE_SERVER),
  render(Document, [route("/", Home)]),
]);

"use client";

import { useState } from "react";
import { useSyncedState } from "rwsdk/use-synced-state/client";

type TodoItem = {
  id: string;
  text: string;
};

const SHARED_KEY = "todos";

export const TodoList = () => {
  // The shared list of to-do items, synchronized across all connected clients
  // via the SyncedStateServer Durable Object. The server is the source of
  // truth, so clients connecting late still see existing items.
  const [todos, setTodos] = useSyncedState<TodoItem[]>([], SHARED_KEY);
  const [input, setInput] = useState("");

  const addItem = () => {
    const text = input.trim();
    if (!text) {
      return;
    }
    setTodos((prev) => [...prev, { id: crypto.randomUUID(), text }]);
    setInput("");
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      addItem();
    }
  };

  return (
    <main style={{ maxWidth: 480, margin: "0 auto", padding: "2rem 1rem" }}>
      <h1>Collaborative To-Do List</h1>
      <p style={{ color: "#666" }}>
        Open this page in another browser window — items added here appear there
        in realtime.
      </p>

      <div style={{ display: "flex", gap: "0.5rem", marginBottom: "1.5rem" }}>
        <input
          data-testid="todo-input"
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={onKeyDown}
          placeholder="Add a new to-do item..."
          style={{
            flex: 1,
            padding: "0.5rem 0.75rem",
            borderRadius: 6,
            border: "1px solid #ccc",
            fontSize: 16,
          }}
        />
        <button
          data-testid="todo-add"
          type="button"
          onClick={addItem}
          style={{
            padding: "0.5rem 1rem",
            borderRadius: 6,
            border: "none",
            background: "#111",
            color: "#fff",
            fontSize: 16,
            cursor: "pointer",
          }}
        >
          Add
        </button>
      </div>

      <ul
        style={{
          listStyle: "none",
          padding: 0,
          margin: 0,
          display: "flex",
          flexDirection: "column",
          gap: "0.5rem",
        }}
      >
        {todos.map((item) => (
          <li
            key={item.id}
            data-testid="todo-item"
            style={{
              padding: "0.75rem 1rem",
              borderRadius: 6,
              border: "1px solid #eee",
              background: "#fafafa",
            }}
          >
            {item.text}
          </li>
        ))}
      </ul>
    </main>
  );
};

import { TodoList } from "./TodoList";

export const Home = () => {
  return <TodoList />;
};

